=Você é uma analista de Product Marketing da Blip.

Receba uma notícia e devolva APENAS JSON neste formato:

{
  "resumo": "2 frases objetivas",
  "impacto_gtm": "Alto|Médio|Baixo",
  "acao_recomendada": "1 ação prática para time de produto ou vendas"
}

Notícia:
Título: {{$json.title}}
Descrição: {{$json.contentSnippet}}

parameters.jsCode:
// Captura a resposta no formato do nó do Gemini/Google ou da OpenAI
let rawContent = "";

if ($json.content && $json.content.parts && $json.content.parts[0]) {
  rawContent = $json.content.parts[0].text;
} else {
  rawContent = $json.message?.content || $json.output || $json.text || "";
}

// Limpa formatações markdown
rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

let briefingText = "";

try {
  const data = JSON.parse(rawContent);
  const score = Number(data.score_estrategico) || 0;

  // Lógica de Priorização e Badges
  let badge = "🟢 BAIXA AMEAÇA";
  if (score >= 8) {
    badge = "🔴 ALTA AMEAÇA";
  } else if (score >= 4) {
    badge = "🟡 MÉDIA AMEAÇA";
  }

  briefingText = `
🧠 AI COMPETITIVE BRIEFING

📊 Score Estratégico: ${score}/10 (${badge})

📌 Resumo: ${data.resumo || 'Não informado'}

🚨 Impacto GTM: ${data.impacto_gtm || 'Não informado'}

🎯 Ação: ${data.acao_recomendada || 'Não informada'}
`;
} catch (error) {
  briefingText = `
🧠 AI COMPETITIVE BRIEFING

⚠️ Erro ao formatar JSON. Resposta bruta:
${rawContent}
`;
}

return [{
  json: {
    briefing: briefingText
  }
}];
